// Package ui holds the web workspace's pages and components (ADR-0052 §4,
// P7): templ templates compiled to Go (the *_templ.go files, generated by
// `make generate` and committed, which CI regenerates and diffs), styled by
// the plain CSS in internal/web/static.
//
// Every statement of the generated code counts in the 100% coverage gate
// (ADR-0052 §10), so templates avoid the constructs whose generated code
// no test can reach: they write text only through T (a catalog message)
// and Value (a value, escaped), set dynamic attributes only through the
// attribute spreads built here (an inline expression carries an error
// branch no string reaches), and pass content as component parameters,
// never as children blocks (whose generated closures always render into
// their parent's buffer, so their own buffer handling never runs). Every page is server-rendered
// semantic HTML that works without script; htmx, when present, only
// replaces fragments.
package ui

//go:generate go tool templ generate

import (
	"context"
	"fmt"
	"io"

	"github.com/a-h/templ"

	"github.com/mustie7iy/agentic-erp/internal/web/i18n"
)

// HTMXConfig is htmx's configuration (ADR-0052 §8): no eval (no hx-on
// handlers, event filters or js: values), no script tags from swapped
// content, requests to this origin only, no indicator styles (an inline
// style the CSP would refuse), and no history snapshots, which htmx keeps
// in localStorage: a page of business data must not outlive the session
// in the browser, so going back reloads it from the server.
const HTMXConfig = `{"allowEval":false,"allowScriptTags":false,"selfRequestsOnly":true,` +
	`"includeIndicatorStyles":false,"historyCacheSize":0,"refreshOnHistoryMiss":true}`

// Shell is what every page's layout needs.
type Shell struct {
	Title   i18n.Key // the page's own title
	Current string   // the path of the navigation entry the page belongs to
	CSS     string   // the stylesheet's content-hashed path
	Script  string   // htmx's content-hashed path
}

// NavItem is one entry of the main navigation.
type NavItem struct {
	Path  string
	Label i18n.Key
}

// Nav is the main navigation. Each job's entry joins it with its screens
// (T73d-T73j).
var Nav = []NavItem{{Path: "/", Label: i18n.NavHome}, {Path: "/health", Label: i18n.NavStatus}}

// T writes the message for k in the request's locale, escaped.
func T(k i18n.Key, args ...any) templ.Component {
	return Text(func(ctx context.Context) string { return i18n.T(ctx, k, args...) })
}

// Text writes the string value gives, escaped.
func Text(value func(context.Context) string) templ.Component {
	return templ.ComponentFunc(func(ctx context.Context, w io.Writer) error {
		if _, err := io.WriteString(w, templ.EscapeString(value(ctx))); err != nil {
			return fmt.Errorf("ui: write text: %w", err)
		}
		return nil
	})
}

// Value writes s, escaped.
func Value(s string) templ.Component {
	return Text(func(context.Context) string { return s })
}

// htmlAttrs are the root element's language and direction.
func htmlAttrs(ctx context.Context) templ.Attributes {
	l, ok := i18n.From(ctx)
	if !ok {
		return templ.Attributes{"lang": "en", "dir": "ltr"}
	}
	return templ.Attributes{"lang": l.Tag.String(), "dir": l.Dir}
}

// title is the document's title: the page's, then the application's.
func title(ctx context.Context, page i18n.Key) templ.Component {
	return T(i18n.PageTitle, i18n.T(ctx, page), i18n.T(ctx, i18n.AppName))
}

// label is an aria-label from the catalog.
func label(ctx context.Context, k i18n.Key) templ.Attributes {
	return templ.Attributes{"aria-label": i18n.T(ctx, k)}
}

// link is an href, sanitised by templ (a javascript: URL becomes
// about:invalid), with aria-current on the page's own entry.
func link(path, current string) templ.Attributes {
	a := templ.Attributes{"href": string(templ.URL(path))}
	if path == current {
		a["aria-current"] = "page"
	}
	return a
}

// stylesheet links the content-hashed stylesheet.
func stylesheet(path string) templ.Attributes {
	return templ.Attributes{"rel": "stylesheet", "href": string(templ.URL(path))}
}

// script loads the content-hashed htmx with the request's nonce (CSP).
func script(ctx context.Context, path string) templ.Attributes {
	return templ.Attributes{"src": string(templ.URL(path)), "nonce": templ.GetNonce(ctx), "defer": true}
}

// htmxMeta is htmx's configuration element.
func htmxMeta() templ.Attributes {
	return templ.Attributes{"name": "htmx-config", "content": HTMXConfig}
}

// labelledBy names an element's label by id.
func labelledBy(id string) templ.Attributes { return templ.Attributes{"aria-labelledby": id} }

// idAttr is an id attribute.
func idAttr(id string) templ.Attributes { return templ.Attributes{"id": id} }

// tagClass is a tag's class: the plain tag, or one of its kinds.
func tagClass(kind string) templ.Attributes {
	if kind == "" {
		return templ.Attributes{"class": "tag"}
	}
	return templ.Attributes{"class": "tag tag--" + kind}
}

// statusRows are the health page's rows.
func statusRows(st Status) []Row {
	revision := T(i18n.StatusUnknown)
	if st.Revision != "" {
		revision = Code(st.Revision)
	}
	return []Row{
		{Key: i18n.StatusService, Value: Code("erp-web")},
		{Key: i18n.StatusState, Value: Tag(i18n.StatusRunning, "success")},
		{Key: i18n.StatusVersion, Value: Code(st.Version)},
		{Key: i18n.StatusRev, Value: revision},
		{Key: i18n.StatusLang, Value: T(i18n.LanguageName)},
	}
}
